	if first.Lower == nil || *first.Lower != "1.0.0" || !first.LowerInclusive {
		t.Fatalf("lower bound mismatch: %+v", first)
	}
	if first.Upper == nil || *first.Upper != "1.2.0" || first.UpperInclusive {
