{"cmd": "cat > /opt/forge/wk03/cell/karlo01/internal/api/vulnerability_test.go <<'EOF'
package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/luwa07832/vuln-registry/internal/store"
)

func newTestRouter(t *testing.T) (http.Handler, *store.Store) {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return NewRouter(st), st
}

func doJSON(t *testing.T, handler http.Handler, method, target string, body string) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != "" {
		reader = bytes.NewReader([]byte(body))
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, target, reader)
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	return rec
}

const validVulnBody = `{
	"id":"CVE-2026-0001",
	"component":"libdemo",
	"ranges":[
		{"lower":"1.0.0","lowerInclusive":true,"upper":"1.2.0","upperInclusive":false},
		{"upper":"0.9.0","upperInclusive":true}
	],
	"severity":"high",
	"fixedVersion":"1.2.0",
	"status":"open"
}`

func TestRegisterVulnerabilitySuccess(t *testing.T) {
	handler, _ := newTestRouter(t)
	rec := doJSON(t, handler, http.MethodPost, "/vulnerabilities", validVulnBody)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d body = %s, want 201", rec.Code, rec.Body.String())
	}
	var record struct {
		ID        string `json:"id"`
		Component string `json:"component"`
		Ranges    []struct {
			Lower          *string `json:"lower"`
			LowerInclusive bool    `json:"lowerInclusive"`
			Upper          *string `json:"upper"`
			UpperInclusive bool    `json:"upperInclusive"`
		} `json:"ranges"`
		Severity     string `json:"severity"`
		FixedVersion string `json:"fixedVersion"`
		Status       string `json:"status"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &record); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if record.ID != "CVE-2026-0001" || record.Component != "libdemo" {
		t.Fatalf("identity mismatch: %+v", record)
	}
	if len(record.Ranges) != 2 || record.Ranges[0].Lower == nil || *record.Ranges[0].Lower != "1.0.0" {
		t.Fatalf("ranges mismatch: %+v", record.Ranges)
	}
	if record.Ranges[1].Lower != nil {
		t.Fatalf("open lower bound must serialize as null: %+v", record.Ranges[1])
	}
	if record.Severity != "high" || record.FixedVersion != "1.2.0" || record.Status != "open" {
		t.Fatalf("scalar mismatch: %+v", record)
	}
}

func TestRegisterDuplicateReturnsFixedConflict(t *testing.T) {
	handler, _ := newTestRouter(t)
	first := doJSON(t, handler, http.MethodPost, "/vulnerabilities", validVulnBody)
	if first.Code != http.StatusCreated {
		t.Fatalf("first status = %d: %s", first.Code, first.Body.String())
	}
	second := doJSON(t, handler, http.MethodPost, "/vulnerabilities", validVulnBody)
	if second.Code != http.StatusConflict {
		t.Fatalf("status = %d, want 409", second.Code)
	}
	if second.Body.String() != "error=DUPLICATE_VULNERABILITY" {
		t.Fatalf("body = %q", second.Body.String())
	}
}

func TestRegisterInvalidInputs(t *testing.T) {
	valid := func() string { return validVulnBody }
	cases := map[string]string{
		"missing field":     `{"id":"CVE-1","component":"libdemo","ranges":[],"severity":"high","fixedVersion":"1.2.0","status":"open"}`,
		"empty id":          strings.Replace(valid(), `"CVE-2026-0001"`, `""`, 1),
		"empty component":   strings.Replace(valid(), `"libdemo"`, `""`, 1),
