		t.Fatalf("open lower bound must serialize as null: %+v", record.Ranges[1])
	}
	if record.Severity != "high" || record.FixedVersion != "1.2.0" || record.Status != "open" {
		t.Fatalf("scalar mismatch: %+v", record)
	}
}

func TestRegisterDuplicateReturnsFixedConflict(t *testing.T) {
	handler, _ := newTestRouter(t)
	first := doJSON(t, handler, http.MethodPost, "/vulnerabilities", validVulnBody)
	if first.Code != http.StatusCreated {
		t.Fatalf("first status = %d: %s", first.Code, first.Body.String())
	}
	second := doJSON(t, handler, http.MethodPost, "/vulnerabilities", validVulnBody)
	if second.Code != http.StatusConflict {
		t.Fatalf("status = %d, want 409", second.Code)
	}
	if second.Body.String() != "error=DUPLICATE_VULNERABILITY" {
		t.Fatalf("body = %q", second.Body.String())
	}
}

func TestRegisterInvalidInputs(t *testing.T) {
	valid := func() string { return validVulnBody }
	cases := map[string]string{
		"missing field":     `{"id":"CVE-1","component":"libdemo","ranges":[],"severity":"high","fixedVersion":"1.2.0","status":"open"}`,
		"empty id":          strings.Replace(valid(), `"CVE-2026-0001"`, `""`, 1),
		"empty component":   strings.Replace(valid(), `"libdemo"`, `""`, 1),
		"reversed bounds":   strings.Replace(valid(), `"lower":"1.0.0"`, `"lower":"9.0.0"`, 1),
		"illegal version":   strings.Replace(valid(), `"fixedVersion":"1.2.0"`, `"fixedVersion":"1.2.x"`, 1),
		"bad severity":      strings.Replace(valid(), `"high"`, `"urgent"`, 1),
		"bad status":        strings.Replace(valid(), `"status":"open"`, `"status":"done"`, 1),
		"bad json":          `{not json`,
		"wrong type":        `{"id":123,"component":"libdemo","ranges":[],"severity":"high","fixedVersion":"1.2.0","status":"open"}`,
	}
	for name, body := range cases {
		handler, st := newTestRouter(t)
		rec := doJSON(t, handler, http.MethodPost, "/vulnerabilities", body)
		if rec.Code != http.StatusBadRequest || rec.Body.String() != "error=INVALID_INPUT" {
			t.Fatalf("%s: status = %d body = %q, want 400 error=INVALID_INPUT", name, rec.Code, rec.Body.String())
		}
		if _, err := st.GetVulnerability("CVE-2026-0001"); err == nil {
			t.Fatalf("%s: failed registration must not write anything", name)
		}
	}
}

func registerVuln(t *testing.T, handler http.Handler, body string) {
	t.Helper()
	rec := doJSON(t, handler, http.MethodPost, "/vulnerabilities", body)
	if rec.Code != http.StatusCreated {
		t.Fatalf("register status = %d body = %s", rec.Code, rec.Body.String())
	}
}

func TestMatchReturnsSortedHitsWithMatchedRanges(t *testing.T) {
	handler, _ := newTestRouter(t)
	registerVuln(t, handler, `{
		"id":"CVE-b","component":"libdemo",
		"ranges":[{"lower":"1.0.0","lowerInclusive":true,"upper":"2.0.0","upperInclusive":false},{"lower":"3.0.0","lowerInclusive":true}],
		"severity":"high","fixedVersion":"2.0.0","status":"open"}`)
	registerVuln(t, handler, `{
		"id":"CVE-a","component":"libdemo",
		"ranges":[{"lower":"1.0.0","lowerInclusive":false,"upper":"2.0.0","upperInclusive":true}],
		"severity":"low","fixedVersion":"2.0.0","status":"in_progress"}`)
	registerVuln(t, handler, `{
		"id":"CVE-c","component":"otherlib","ranges":[{}],
		"severity":"critical","fixedVersion":"9.0.0","status":"open"}`)

	rec := doJSON(t, handler, http.MethodGet, "/vulnerabilities/match?component=libdemo&version=3.1.0", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d: %s", rec.Code, rec.Body.String())
	}
	var hits []struct {
		ID            string `json:"id"`
		Component     string `json:"component"`
		MatchedRanges []struct {
			Lower *string `json:"lower"`
			Upper *string `json:"upper"`
		} `json:"matchedRanges"`
		Severity     string `json:"severity"`
		FixedVersion string `json:"fixedVersion"`
		Status       string `json:"status"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &hits); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(hits) != 1 || hits[0].ID != "CVE-b" {
		t.Fatalf("hits = %+v", hits)
	}
	if len(hits[0].MatchedRanges) != 1 || hits[0].MatchedRanges[0].Upper != nil {
		t.Fatalf("matched range = %+v", hits[0].MatchedRanges)
	}
	if hits[0].Component != "libdemo" || hits[0].Severity != "high" || hits[0].FixedVersion != "2.0.0" || hits[0].Status != "open" {
		t.Fatalf("hit fields incomplete: %+v", hits[0])
	}

	both := doJSON(t, handler, http.MethodGet, "/vulnerabilities/match?component=libdemo&version=1.5.0", "")
	if both.Code != http.StatusOK {
		t.Fatalf("status = %d", both.Code)
	}
	var bothHits []struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(both.Body.Bytes(), &bothHits); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(bothHits) != 2 || bothHits[0].ID != "CVE-a" || bothHits[1].ID != "CVE-b" {
		t.Fatalf("order/ids = %+v, want CVE-a then CVE-b", bothHits)
	}

	// Boundary semantics: lower exclusive at 1.0.0, upper inclusive at 2.0.0.
	if doJSON(t, handler, http.MethodGet, "/vulnerabilities/match?component=libdemo&version=1.0.0", "").Body.String() != `[{"id":"CVE-b","component":"libdemo","matchedRanges":[{"lower":"1.0.0","lowerInclusive":true,"upper":"2.0.0","upperInclusive":false}],"severity":"high","fixedVersion":"2.0.0","status":"open"}]` {
		t.Fatal("exclusive lower boundary hit unexpected records")
	}
}

