func TestMatchIsCaseSensitiveAndValidates(t *testing.T) {
	handler, _ := newTestRouter(t)
	registerVuln(t, handler, validVulnBody)
	rec := doJSON(t, handler, http.MethodGet, "/vulnerabilities/match?component=LibDemo&version=1.1.0", "")
	if rec.Code != http.StatusOK || rec.Body.String() != "[]" {
		t.Fatalf("case-sensitive match: status=%d body=%s", rec.Code, rec.Body.String())
	}
	for _, target := range []string{
		"/vulnerabilities/match?version=1.0.0",
		"/vulnerabilities/match?component=libdemo",
		"/vulnerabilities/match?component=libdemo&version=bad",
		"/vulnerabilities/match?component=&version=1.0.0",
	} {
		bad := doJSON(t, handler, http.MethodGet, target, "")
		if bad.Code != http.StatusBadRequest || bad.Body.String() != "error=INVALID_INPUT" {
			t.Fatalf("%s: status=%d body=%q", target, bad.Code, bad.Body.String())
		}
	}
}

func TestStatusUpdateSuccessNotFoundAndInvalid(t *testing.T) {
	handler, _ := newTestRouter(t)
	registerVuln(t, handler, validVulnBody)

	missing := doJSON(t, handler, http.MethodPatch, "/vulnerabilities/NOPE/status", `{"status":"fixed"}`)
	if missing.Code != http.StatusNotFound || missing.Body.String() != "error=VULNERABILITY_NOT_FOUND" {
		t.Fatalf("missing: status=%d body=%q", missing.Code, missing.Body.String())
	}

	for _, body := range []string{`{}`, `{"status":"done"}`, `{"status":""}`, `broken`} {
		bad := doJSON(t, handler, http.MethodPatch, "/vulnerabilities/CVE-2026-0001/status", body)
		if bad.Code != http.StatusBadRequest || bad.Body.String() != "error=INVALID_INPUT" {
			t.Fatalf("body %q: status=%d resp=%q", body, bad.Code, bad.Body.String())
		}
	}

	ok := doJSON(t, handler, http.MethodPatch, "/vulnerabilities/CVE-2026-0001/status", `{"status":"ignored"}`)
	if ok.Code != http.StatusOK {
		t.Fatalf("status=%d body=%s", ok.Code, ok.Body.String())
	}
	var record struct {
		ID           string `json:"id"`
		Status       string `json:"status"`
		Severity     string `json:"severity"`
		FixedVersion string `json:"fixedVersion"`
	}
	if err := json.Unmarshal(ok.Body.Bytes(), &record); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if record.ID != "CVE-2026-0001" || record.Status != "ignored" || record.Severity != "high" || record.FixedVersion != "1.2.0" {
		t.Fatalf("updated record mismatch: %+v", record)
	}

	again := doJSON(t, handler, http.MethodGet, "/vulnerabilities/match?component=libdemo&version=1.1.0", "")
	var hits []struct {
		Status string `json:"status"`
	}
	if err := json.Unmarshal(again.Body.Bytes(), &hits); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(hits) != 1 || hits[0].Status != "ignored" {
		t.Fatalf("persisted status hits = %+v", hits)
	}
}
